import re

NUMBER_RE = re.compile(r"-?\d+")


class StackUnderflowError(Exception):
    pass


def _pop(stack, n):
    if len(stack) < n:
        raise StackUnderflowError("Insufficient number of items in stack")
    return [stack.pop() for _ in range(n)]


def _add(stack):
    b, a = _pop(stack, 2)
    stack.append(a + b)


def _sub(stack):
    b, a = _pop(stack, 2)
    stack.append(a - b)


def _mul(stack):
    b, a = _pop(stack, 2)
    stack.append(a * b)


def _div(stack):
    b, a = _pop(stack, 2)
    if b == 0:
        raise ZeroDivisionError("divide by zero")
    # Integer division truncates toward zero, like Forth (not Python's //).
    q = abs(a) // abs(b)
    stack.append(q if (a >= 0) == (b >= 0) else -q)


def _dup(stack):
    a = _pop(stack, 1)[0]
    stack.append(a)
    stack.append(a)


def _drop(stack):
    _pop(stack, 1)


def _swap(stack):
    b, a = _pop(stack, 2)
    stack.append(b)
    stack.append(a)


def _over(stack):
    b, a = _pop(stack, 2)
    stack.append(a)
    stack.append(b)
    stack.append(a)


BUILTINS = {
    "+": _add,
    "-": _sub,
    "*": _mul,
    "/": _div,
    "dup": _dup,
    "drop": _drop,
    "swap": _swap,
    "over": _over,
}


def evaluate(input_data):
    stack = []
    words = {}

    def exec_token(token):
        if NUMBER_RE.fullmatch(token):
            stack.append(int(token))
            return
        name = token.lower()
        if name in words:
            for body_token in words[name]:
                exec_token(body_token)
        elif name in BUILTINS:
            BUILTINS[name](stack)
        else:
            raise ValueError("undefined operation")

    for line in input_data:
        tokens = line.split()
        i = 0
        while i < len(tokens):
            if tokens[i] == ":":
                i += 1
                name = tokens[i].lower()
                if NUMBER_RE.fullmatch(name):
                    raise ValueError("illegal operation")
                i += 1
                body = []
                while tokens[i] != ";":
                    body.append(tokens[i].lower())
                    i += 1
                words[name] = body
                i += 1  # skip the terminating ";"
            else:
                exec_token(tokens[i])
                i += 1

    return stack

